qs = {}
for f in sorted(glob.glob(BASE + '*.json')):
    for q in json.load(open(f)): qs[q['id']] = q
bad = 0
for id_, q in qs.items():
    r = REC[id_]
    key = [c['t'] for c in q['c'] if c.get('k')][0]
    if r['kind'] == 'val':
        want = eval(r['expr'])
        ok = (want == key) and all(c['t'] != want for c in q['c'] if not c.get('k'))
        print(('OK ' if ok else 'NG '), id_, '|', q['q'][:50], '→', want)
    else:
        tr = [t for t, b in r['items'].items() if eval(b)]
        ok = tr == [key] and set(r['items']) == {c['t'] for c in q['c']}
        print(('OK ' if ok else 'NG '), id_, '|', q['q'][:50], '→', tr)
    if not ok: bad += 1
print('問題', len(qs), 'NG', bad)
sys.exit(1 if bad else 0)
